#!/usr/bin/env node
// Extract memory values from an ELF binary, mapping loadable segments at
// base 0x400000 (matching CLE/angr's default PIE load base) and emitting
// each 4-byte little-endian word keyed by its virtual address.
//
// Relocations are handled the way the loader would resolve them in memory:
//  * R_X86_64_RELATIVE words become BASE + addend (deterministic).
//  * Words targeted by symbol relocations (GLOB_DAT / JUMP_SLOT) resolve to
//    loader-internal / external addresses that are not reproducible, so those
//    words are omitted rather than emitted with a wrong value.
'use strict';
const fs = require('fs');

const path = process.argv[2];
if (!path) { console.error('usage: node extract.js <binary>'); process.exit(1); }
const buf = fs.readFileSync(path);

if (!(buf[0] === 0x7f && buf[1] === 0x45 && buf[2] === 0x4c && buf[3] === 0x46))
  throw new Error('not an ELF file');
const is64 = buf[4] === 2;
const le = buf[5] === 1;
if (!is64) throw new Error('only ELF64 supported');

function u16(o){ return le ? buf.readUInt16LE(o) : buf.readUInt16BE(o); }
function u32(o){ return le ? buf.readUInt32LE(o) : buf.readUInt32BE(o); }
function u64(o){
  const lo = le ? buf.readUInt32LE(o)   : buf.readUInt32BE(o+4);
  const hi = le ? buf.readUInt32LE(o+4) : buf.readUInt32BE(o);
  return hi * 0x100000000 + lo;
}

const e_phoff = u64(0x20);
const e_phentsize = u16(0x36);
const e_phnum = u16(0x38);

const PT_LOAD = 1, PT_DYNAMIC = 2;
const BASE = 0x400000;
const R_X86_64_RELATIVE = 8;

// Collect PT_LOAD segments and the PT_DYNAMIC segment.
const loads = [];
let dyn = null;
for (let i = 0; i < e_phnum; i++) {
  const ph = e_phoff + i * e_phentsize;
  const p_type = u32(ph + 0x00);
  const seg = {
    offset: u64(ph + 0x08), vaddr: u64(ph + 0x10),
    filesz: u64(ph + 0x20), memsz: u64(ph + 0x28),
  };
  if (p_type === PT_LOAD) loads.push(seg);
  else if (p_type === PT_DYNAMIC) dyn = seg;
}

// Map a virtual address to a file offset using the PT_LOAD segments.
function vaddrToOffset(v) {
  for (const s of loads) {
    if (v >= s.vaddr && v < s.vaddr + s.filesz) return s.offset + (v - s.vaddr);
  }
  return -1;
}

// Parse the dynamic table to locate relocation tables.
let relaAddr = 0, relaSz = 0, jmprelAddr = 0, pltrelSz = 0;
if (dyn) {
  const base = vaddrToOffset(dyn.vaddr);
  const end = base + dyn.filesz;
  for (let o = base; o + 16 <= end; o += 16) {
    const tag = u64(o), val = u64(o + 8);
    if (tag === 0) break;
    else if (tag === 7)  relaAddr = val;   // DT_RELA
    else if (tag === 8)  relaSz = val;     // DT_RELASZ
    else if (tag === 23) jmprelAddr = val; // DT_JMPREL
    else if (tag === 2)  pltrelSz = val;   // DT_PLTRELSZ
  }
}

// relative[vaddr] = resolved value ; skip = set of reloc-target vaddrs to omit.
const relative = new Map();
const skip = new Set();
function parseRela(addr, size) {
  if (!addr || !size) return;
  const off = vaddrToOffset(addr);
  if (off < 0) return;
  for (let o = off; o + 24 <= off + size; o += 24) {
    const r_offset = u64(o);
    const r_type = u32(o + 8);        // low 32 bits of r_info
    const r_addend = u64(o + 16);
    if (r_type === R_X86_64_RELATIVE) relative.set(r_offset, BASE + r_addend);
    else skip.add(r_offset);
  }
}
parseRela(relaAddr, relaSz);
parseRela(jmprelAddr, pltrelSz);

// Emit 4-byte little-endian words for every loadable word.
const out = {};
for (const s of loads) {
  const seg = Buffer.alloc(s.memsz);
  const n = Math.min(s.filesz, buf.length - s.offset);
  if (n > 0) buf.copy(seg, 0, s.offset, s.offset + n);
  for (let off = 0; off + 4 <= s.memsz; off += 4) {
    const v = s.vaddr + off;
    if (skip.has(v)) continue;               // unresolved/external target
    let val;
    if (relative.has(v)) val = relative.get(v) >>> 0 || relative.get(v);
    else val = seg.readUInt32LE(off);
    out[BASE + v] = relative.has(v) ? relative.get(v) : val;
  }
}

process.stdout.write(JSON.stringify(out));

